// Built-in datasets and localStorage management for Decision Tree Tabular Datasets

export type TabularDataset = {
  id: string;
  name: string;
  features: string[];
  featureTypes: Record<string, 'categorical' | 'numerical'>;
  targetName: string;
  targetClasses: string[];
  data: Record<string, any>[];
};

